  1→// iOS-specific: native AVAudioRecorder, WKWebView termination recovery.
  2→
  3→use objc::declare::ClassDecl;
  4→use objc::runtime::{Class, Object, Protocol, Sel, BOOL, NO, YES};
  5→use objc::{msg_send, sel, sel_impl};
  6→use std::{
  7→    collections::HashMap,
  8→    ffi::{CStr, CString},
  9→    fs,
 10→    os::raw::{c_char, c_int},
 11→    path::{Path, PathBuf},
 12→    ptr,
 13→    sync::{mpsc, Mutex, OnceLock},
 14→};
 15→use tauri::Manager;
 16→
 17→use crate::{app_data_dir, now_ms};
 18→
 19→// ── Constants ──────────────────────────────────────────────────────────────────
 20→
 21→const IOS_WEBVIEW_TERMINATION_PROXY_CLASS: &str = "TypeWebViewTerminationProxy";
 22→const IOS_WEBVIEW_RELOAD_THROTTLE_MS: i64 = 1_000;
 23→pub(crate) const IOS_AUDIO_MIME_TYPE: &str = "audio/mp4";
 24→const IOS_AUDIO_FILE_EXT: &str = "m4a";
 25→const K_AUDIO_FORMAT_MPEG4AAC: u32 = 0x6161_6320;
 26→const RTLD_NOW: c_int = 2;
 27→const UI_USER_INTERFACE_STYLE_LIGHT: isize = 1;
 28→const UI_USER_INTERFACE_STYLE_DARK: isize = 2;
 29→
 30→// ── FFI ────────────────────────────────────────────────────────────────────────
 31→
 32→unsafe extern "C" {
 33→    fn dlopen(filename: *const c_char, flag: c_int) -> *mut core::ffi::c_void;
 34→    fn dlerror() -> *const c_char;
 35→}
 36→
 37→// ── Types ──────────────────────────────────────────────────────────────────────
 38→
 39→/// Holds the active AVAudioRecorder pointer and metadata.
 40→pub(crate) struct IosNativeRecorderState {
 41→    pub(crate) recorder_ptr: usize,
 42→    pub(crate) output_path: PathBuf,
 43→    pub(crate) mime_type: String,
 44→    pub(crate) started_ms: Option<i64>,
 45→}
 46→
 47→// ── Statics ────────────────────────────────────────────────────────────────────
 48→
 49→static IOS_NATIVE_RECORDER: OnceLock<Mutex<Option<IosNativeRecorderState>>> = OnceLock::new();
 50→static IOS_WEBVIEW_TERMINATION_PROXIES: OnceLock<Mutex<HashMap<usize, usize>>> = OnceLock::new();
 51→static IOS_WEBVIEW_TERMINATION_PROXY_CLASS_PTR: OnceLock<usize> = OnceLock::new();
 52→
 53→// ── Recorder state ─────────────────────────────────────────────────────────────
 54→
 55→pub(crate) fn ios_native_recorder_state() -> &'static Mutex<Option<IosNativeRecorderState>> {
 56→    IOS_NATIVE_RECORDER.get_or_init(|| Mutex::new(None))
 57→}
 58→
 59→// ── WKWebView termination recovery ────────────────────────────────────────────
 60→
 61→fn ios_webview_termination_proxies() -> &'static Mutex<HashMap<usize, usize>> {
 62→    IOS_WEBVIEW_TERMINATION_PROXIES.get_or_init(|| Mutex::new(HashMap::new()))
 63→}
 64→
 65→fn ios_webview_termination_proxy_class() -> &'static Class {
 66→    let class_ptr = IOS_WEBVIEW_TERMINATION_PROXY_CLASS_PTR.get_or_init(|| {
 67→        if let Some(existing) = Class::get(IOS_WEBVIEW_TERMINATION_PROXY_CLASS) {
 68→            return existing as *const Class as usize;
 69→        }
 70→
 71→        let superclass = Class::get("NSObject")
 72→            .expect("NSObject missing while installing iOS webview termination proxy");
 73→        let mut decl = ClassDecl::new(IOS_WEBVIEW_TERMINATION_PROXY_CLASS, superclass)
 74→            .expect("Failed to declare iOS webview termination proxy class");
 75→        if let Some(protocol) = Protocol::get("WKNavigationDelegate") {
 76→            decl.add_protocol(protocol);
 77→        }
 78→        decl.add_ivar::<*mut Object>("originalDelegate");
 79→        decl.add_ivar::<i64>("lastReloadMs");
 80→        unsafe {
 81→            decl.add_method(
 82→                sel!(dealloc),
 83→                ios_webview_termination_proxy_dealloc as extern "C" fn(&mut Object, Sel),
 84→            );
 85→            decl.add_method(
 86→                sel!(respondsToSelector:),
 87→                ios_webview_termination_proxy_responds_to_selector
 88→                    as extern "C" fn(&Object, Sel, Sel) -> BOOL,
 89→            );
 90→            decl.add_method(
 91→                sel!(forwardingTargetForSelector:),
 92→                ios_webview_termination_proxy_forwarding_target_for_selector
 93→                    as extern "C" fn(&Object, Sel, Sel) -> *mut Object,
 94→            );
 95→            decl.add_method(
 96→                sel!(webViewWebContentProcessDidTerminate:),
 97→                ios_webview_termination_proxy_process_did_terminate
 98→                    as extern "C" fn(&mut Object, Sel, *mut Object),
 99→            );
100→        }
101→
102→        decl.register() as *const Class as usize
103→    });
104→
105→    unsafe { &*(*class_ptr as *const Class) }
106→}
107→
108→extern "C" fn ios_webview_termination_proxy_dealloc(this: &mut Object, _cmd: Sel) {
109→    unsafe {
110→        let original_delegate = *this.get_ivar::<*mut Object>("originalDelegate");
111→        if !original_delegate.is_null() {
112→            let _: () = msg_send![original_delegate, release];
113→            this.set_ivar("originalDelegate", ptr::null_mut::<Object>());
114→        }
115→
116→        let superclass = this
117→            .class()
118→            .superclass()
119→            .expect("iOS webview termination proxy superclass missing");
120→        let _: () = msg_send![super(this, superclass), dealloc];
121→    }
122→}
123→
124→extern "C" fn ios_webview_termination_proxy_responds_to_selector(
125→    this: &Object,
126→    _cmd: Sel,
127→    selector: Sel,
128→) -> BOOL {
129→    unsafe {
130→        if selector == sel!(webViewWebContentProcessDidTerminate:) {
131→            return YES;
132→        }
133→
134→        let original_delegate = *this.get_ivar::<*mut Object>("originalDelegate");
135→        if !original_delegate.is_null() {
136→            let responds: BOOL = msg_send![original_delegate, respondsToSelector: selector];
137→            if responds == YES {
138→                return YES;
139→            }
140→        }
141→
142→        let superclass = this
143→            .class()
144→            .superclass()
145→            .expect("iOS webview termination proxy superclass missing");
146→        msg_send![super(this, superclass), respondsToSelector: selector]
147→    }
148→}
149→
150→extern "C" fn ios_webview_termination_proxy_forwarding_target_for_selector(
151→    this: &Object,
152→    _cmd: Sel,
153→    selector: Sel,
154→) -> *mut Object {
155→    unsafe {
156→        if selector == sel!(webViewWebContentProcessDidTerminate:) {
157→            return ptr::null_mut();
158→        }
159→
160→        let original_delegate = *this.get_ivar::<*mut Object>("originalDelegate");
161→        if !original_delegate.is_null() {
162→            let responds: BOOL = msg_send![original_delegate, respondsToSelector: selector];
163→            if responds == YES {
164→                return original_delegate;
165→            }
166→        }
167→
168→        let superclass = this
169→            .class()
170→            .superclass()
171→            .expect("iOS webview termination proxy superclass missing");
172→        msg_send![super(this, superclass), forwardingTargetForSelector: selector]
173→    }
174→}
175→
176→extern "C" fn ios_webview_termination_proxy_process_did_terminate(
177→    this: &mut Object,
178→    _cmd: Sel,
179→    webview: *mut Object,
180→) {
181→    unsafe {
182→        if webview.is_null() {
183→            return;
184→        }
185→
186→        let now = now_ms().unwrap_or(0);
187→        let last_reload_ms = *this.get_ivar::<i64>("lastReloadMs");
188→        let should_reload =
189→            now <= 0 || now.saturating_sub(last_reload_ms) >= IOS_WEBVIEW_RELOAD_THROTTLE_MS;
190→        if should_reload {
191→            if now > 0 {
192→                this.set_ivar("lastReloadMs", now);
193→            }
194→            let _: () = msg_send![webview, reload];
195→            println!("[ios] WKWebView content process terminated. Reload requested.");
196→        }
197→
198→        let original_delegate = *this.get_ivar::<*mut Object>("originalDelegate");
199→        if !original_delegate.is_null() {
200→            let responds: BOOL = msg_send![
201→                original_delegate,
202→                respondsToSelector: sel!(webViewWebContentProcessDidTerminate:)
203→            ];
204→            if responds == YES {
205→                let _: () = msg_send![
206→                    original_delegate,
207→                    webViewWebContentProcessDidTerminate: webview
208→                ];
209→            }
210→        }
211→    }
212→}
213→
214→unsafe fn install_ios_webview_termination_recovery_for_webview(
215→    webview: *mut Object,
216→) -> Result<(), String> {
217→    if webview.is_null() {
218→        return Err("WKWebView handle is null.".to_string());
219→    }
220→
221→    let proxy_class = ios_webview_termination_proxy_class();
222→    let current_delegate: *mut Object = msg_send![webview, navigationDelegate];
223→    if !current_delegate.is_null() {
224→        let delegate_class: *const Class = msg_send![current_delegate, class];
225→        if std::ptr::eq(delegate_class, proxy_class as *const Class) {
226→            return Ok(());
227→        }
228→    }
229→
230→    let proxy_alloc: *mut Object = msg_send![proxy_class, alloc];
231→    if proxy_alloc.is_null() {
232→        return Err("Failed to allocate iOS webview termination proxy.".to_string());
233→    }
234→    let proxy: *mut Object = msg_send![proxy_alloc, init];
235→    if proxy.is_null() {
236→        return Err("Failed to initialize iOS webview termination proxy.".to_string());
237→    }
238→
239→    if !current_delegate.is_null() {
240→        let _: *mut Object = msg_send![current_delegate, retain];
241→    }
242→    (*proxy).set_ivar("originalDelegate", current_delegate);
243→    (*proxy).set_ivar("lastReloadMs", 0_i64);
244→
245→    // WKWebView.navigationDelegate is weak, so keep the proxy alive.
246→    let _: *mut Object = msg_send![proxy, retain];
247→    let _: () = msg_send![webview, setNavigationDelegate: proxy];
248→
249→    let mut proxies = ios_webview_termination_proxies()
250→        .lock()
251→        .map_err(|_| "Failed to lock iOS webview proxy registry.".to_string())?;
252→    if let Some(previous_proxy_addr) = proxies.insert(webview as usize, proxy as usize) {
253→        if previous_proxy_addr != proxy as usize {
254→            let previous_proxy = previous_proxy_addr as *mut Object;
255→            if !previous_proxy.is_null() {
256→                let _: () = msg_send![previous_proxy, release];
257→            }
258→        }
259→    }
260→
261→    Ok(())
262→}
263→
264→/// Install WKWebView termination recovery on the main webview.
265→pub(crate) fn install_ios_webview_termination_recovery(app: &tauri::AppHandle) {
266→    let Some(window) = app.get_webview_window("main") else {
267→        return;
268→    };
269→
270→    if let Err(error) = window.with_webview(|platform_webview| unsafe {
271→        let webview = platform_webview.inner() as *mut Object;
272→        if let Err(error) = install_ios_webview_termination_recovery_for_webview(webview) {
273→            println!(
274→                "[ios] Failed to install WKWebView termination recovery: {}",
275→                error
276→            );
277→        }
278→    }) {
279→        println!(
280→            "[ios] Failed to access WKWebView for termination recovery: {}",
281→            error
282→        );
283→    }
284→}
285→
286→/// Release all retained proxy objects.
287→pub(crate) fn release_ios_webview_termination_proxies() {
288→    let Some(proxies) = IOS_WEBVIEW_TERMINATION_PROXIES.get() else {
289→        return;
290→    };
291→    let mut proxies = match proxies.lock() {
292→        Ok(guard) => guard,
293→        Err(poisoned) => poisoned.into_inner(),
294→    };
295→
296→    for (_, proxy_addr) in proxies.drain() {
297→        let proxy = proxy_addr as *mut Object;
298→        if proxy.is_null() {
299→            continue;
300→        }
301→        unsafe {
302→            let _: () = msg_send![proxy, release];
303→        }
304→    }
305→}
306→
307→// ── AVFoundation ───────────────────────────────────────────────────────────────
308→
309→pub(crate) fn ensure_avfoundation_loaded() -> Result<(), String> {
310→    let framework_path =
311→        CString::new("/System/Library/Frameworks/AVFoundation.framework/AVFoundation")
312→            .map_err(|_| "Failed to load AVFoundation framework path.".to_string())?;
313→    unsafe {
314→        let handle = dlopen(framework_path.as_ptr(), RTLD_NOW);
315→        if !handle.is_null() {
316→            return Ok(());
317→        }
318→        let error_ptr = dlerror();
319→        if error_ptr.is_null() {
320→            return Err("Failed to load AVFoundation framework.".to_string());
321→        }
322→        let message = CStr::from_ptr(error_ptr).to_string_lossy().to_string();
323→        Err(format!(
324→            "Failed to load AVFoundation framework: {}",
325→            message
326→        ))
327→    }
328→}
