330→fn ns_class(name: &str) -> Result<&'static Class, String> {
331→    Class::get(name).ok_or_else(|| format!("Missing iOS runtime class: {}", name))
332→}
333→
334→fn ns_string(value: &str) -> Result<*mut Object, String> {
335→    let c_value =
336→        CString::new(value).map_err(|_| "Failed to convert string for iOS runtime.".to_string())?;
337→    unsafe {
338→        let class = ns_class("NSString")?;
339→        let result: *mut Object = msg_send![class, stringWithUTF8String: c_value.as_ptr()];
340→        if result.is_null() {
341→            return Err("Failed to create NSString.".to_string());
342→        }
343→        Ok(result)
344→    }
345→}
346→
347→fn ns_error_message(error: *mut Object, fallback: &str) -> String {
348→    if error.is_null() {
349→        return fallback.to_string();
350→    }
351→    unsafe {
352→        let localized: *mut Object = msg_send![error, localizedDescription];
353→        if localized.is_null() {
354→            return fallback.to_string();
355→        }
356→        let c_message: *const c_char = msg_send![localized, UTF8String];
357→        if c_message.is_null() {
358→            return fallback.to_string();
359→        }
360→        CStr::from_ptr(c_message).to_string_lossy().to_string()
361→    }
362→}
