364→/// Configure the iOS audio session for recording.
365→pub(crate) fn configure_ios_audio_for_recording() -> Result<(), String> {
366→    unsafe {
367→        let av_audio_class = ns_class("AVAudioSession")?;
368→        let av_audio: *mut Object = msg_send![av_audio_class, sharedInstance];
369→        if av_audio.is_null() {
370→            return Err("Failed to access AVAudioSession.".to_string());
371→        }
372→        let category = ns_string("AVAudioSessionCategoryPlayAndRecord")?;
373→        let mut error: *mut Object = ptr::null_mut();
374→        let category_ok: BOOL = msg_send![av_audio, setCategory: category error: &mut error];
375→        if category_ok == NO {
376→            return Err(ns_error_message(
377→                error,
378→                "Failed to set AVAudioSession category.",
379→            ));
380→        }
381→        let active_ok: BOOL = msg_send![av_audio, setActive: YES error: &mut error];
382→        if active_ok == NO {
383→            return Err(ns_error_message(
384→                error,
385→                "Failed to activate AVAudioSession.",
386→            ));
387→        }
388→    }
389→    Ok(())
390→}
