392→pub(crate) fn deactivate_ios_audio() {
393→    unsafe {
394→        if let Some(av_audio_class) = Class::get("AVAudioSession") {
395→            let av_audio: *mut Object = msg_send![av_audio_class, sharedInstance];
396→            if av_audio.is_null() {
397→                return;
398→            }
399→            let mut error: *mut Object = ptr::null_mut();
400→            let _: BOOL = msg_send![av_audio, setActive: NO error: &mut error];
401→        }
402→    }
403→}
