405→/// Create and start an AVAudioRecorder at the given output path.
406→pub(crate) fn create_ios_audio_recorder(output_path: &Path) -> Result<*mut Object, String> {
407→    unsafe {
408→        let dictionary_class = ns_class("NSMutableDictionary")?;
409→        let settings: *mut Object = msg_send![dictionary_class, dictionary];
410→        if settings.is_null() {
411→            return Err("Failed to create recorder settings.".to_string());
412→        }
413→
414→        let number_class = ns_class("NSNumber")?;
415→        let format_key = ns_string("AVFormatIDKey")?;
416→        let sample_rate_key = ns_string("AVSampleRateKey")?;
417→        let channels_key = ns_string("AVNumberOfChannelsKey")?;
418→        let bitrate_key = ns_string("AVEncoderBitRateKey")?;
419→        let quality_key = ns_string("AVEncoderAudioQualityKey")?;
420→
421→        let format_value: *mut Object =
422→            msg_send![number_class, numberWithUnsignedInt: K_AUDIO_FORMAT_MPEG4AAC];
423→        let sample_rate_value: *mut Object = msg_send![number_class, numberWithDouble: 44_100.0f64];
424→        let channels_value: *mut Object = msg_send![number_class, numberWithInt: 1i32];
425→        let bitrate_value: *mut Object = msg_send![number_class, numberWithInt: 128_000i32];
426→        let quality_value: *mut Object = msg_send![number_class, numberWithInt: 96i32];
427→
428→        let _: () = msg_send![settings, setObject: format_value forKey: format_key];
429→        let _: () = msg_send![settings, setObject: sample_rate_value forKey: sample_rate_key];
430→        let _: () = msg_send![settings, setObject: channels_value forKey: channels_key];
431→        let _: () = msg_send![settings, setObject: bitrate_value forKey: bitrate_key];
432→        let _: () = msg_send![settings, setObject: quality_value forKey: quality_key];
433→
434→        let path_ns = ns_string(&output_path.to_string_lossy())?;
435→        let url_class = ns_class("NSURL")?;
436→        let url: *mut Object = msg_send![url_class, fileURLWithPath: path_ns];
437→        if url.is_null() {
438→            return Err("Failed to build native recorder output URL.".to_string());
439→        }
440→
441→        let recorder_class = ns_class("AVAudioRecorder")?;
442→        let alloc: *mut Object = msg_send![recorder_class, alloc];
443→        if alloc.is_null() {
444→            return Err("Failed to allocate AVAudioRecorder.".to_string());
445→        }
446→        let mut error: *mut Object = ptr::null_mut();
447→        let recorder: *mut Object =
448→            msg_send![alloc, initWithURL: url settings: settings error: &mut error];
449→        if recorder.is_null() {
450→            return Err(ns_error_message(
451→                error,
452→                "Failed to initialize AVAudioRecorder.",
453→            ));
454→        }
455→
456→        let prepared: BOOL = msg_send![recorder, prepareToRecord];
457→        if prepared == NO {
458→            let _: () = msg_send![recorder, release];
459→            return Err("Failed to prepare AVAudioRecorder.".to_string());
460→        }
461→        let started: BOOL = msg_send![recorder, record];
462→        if started == NO {
463→            let _: () = msg_send![recorder, release];
464→            return Err("Failed to start AVAudioRecorder.".to_string());
465→        }
466→        Ok(recorder)
467→    }
468→}
