494→/// Allocate a unique file path for a native recording in app data.
495→pub(crate) fn next_native_recording_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
496→    let root = app_data_dir(app)?.join("native-recordings");
497→    fs::create_dir_all(&root).map_err(|error| error.to_string())?;
498→    let timestamp = now_ms().unwrap_or(0);
499→    for attempt in 0..=512usize {
500→        let suffix = if attempt == 0 {
501→            format!("recording-{}", timestamp)
502→        } else {
503→            format!("recording-{}-{}", timestamp, attempt)
504→        };
505→        let path = root.join(format!("{}.{}", suffix, IOS_AUDIO_FILE_EXT));
506→        if !path.exists() {
507→            return Ok(path);
508→        }
509→    }
510→    Err("Failed to allocate native recording filename.".to_string())
511→}
