513→unsafe fn apply_ios_interface_style_to_webview(
514→    webview: *mut Object,
515→    style: isize,
516→) -> Result<(), String> {
517→    if webview.is_null() {
518→        return Err("WKWebView handle is null.".to_string());
519→    }
520→
521→    let _: () = msg_send![webview, setOverrideUserInterfaceStyle: style];
522→
523→    let scroll_view: *mut Object = msg_send![webview, scrollView];
524→    if !scroll_view.is_null() {
525→        let _: () = msg_send![scroll_view, setOverrideUserInterfaceStyle: style];
526→    }
527→
528→    let window: *mut Object = msg_send![webview, window];
529→    if !window.is_null() {
530→        let _: () = msg_send![window, setOverrideUserInterfaceStyle: style];
531→
532→        let mut controller: *mut Object = msg_send![window, rootViewController];
533→        while !controller.is_null() {
534→            let _: () = msg_send![controller, setOverrideUserInterfaceStyle: style];
535→            let next_controller: *mut Object = msg_send![controller, presentedViewController];
536→            if next_controller.is_null() {
537→                break;
538→            }
539→            controller = next_controller;
540→        }
541→    }
542→
543→    Ok(())
544→}
