546→pub(crate) fn set_ios_native_theme(app: &tauri::AppHandle, theme: &str) -> Result<(), String> {
547→    let normalized = theme.trim().to_ascii_lowercase();
548→    let style = match normalized.as_str() {
549→        "dark" => UI_USER_INTERFACE_STYLE_DARK,
550→        "light" => UI_USER_INTERFACE_STYLE_LIGHT,
551→        _ => return Err(format!("Unsupported iOS theme: {}", theme)),
552→    };
553→
554→    let Some(window) = app.get_webview_window("main") else {
555→        return Ok(());
556→    };
557→
558→    let (tx, rx) = mpsc::sync_channel(1);
559→    window
560→        .with_webview(move |platform_webview| {
561→            let result = unsafe {
562→                let webview = platform_webview.inner() as *mut Object;
563→                apply_ios_interface_style_to_webview(webview, style)
564→            };
565→            let _ = tx.send(result);
566→        })
567→        .map_err(|error| error.to_string())?;
568→
569→    rx.recv()
570→        .map_err(|_| "Failed to receive the iOS theme update result.".to_string())?
571→}
