573→unsafe fn ios_top_presenting_view_controller(webview: *mut Object) -> Result<*mut Object, String> {
574→    if webview.is_null() {
575→        return Err("WKWebView handle is null.".to_string());
576→    }
577→
578→    let window: *mut Object = msg_send![webview, window];
579→    if window.is_null() {
580→        return Err("Failed to resolve the iOS window for file export.".to_string());
581→    }
582→
583→    let mut controller: *mut Object = msg_send![window, rootViewController];
584→    if controller.is_null() {
585→        return Err("Failed to resolve the iOS root view controller.".to_string());
586→    }
587→
588→    loop {
589→        let presented: *mut Object = msg_send![controller, presentedViewController];
590→        if presented.is_null() {
591→            break;
592→        }
593→        controller = presented;
594→    }
595→
596→    Ok(controller)
597→}
