599→unsafe fn present_ios_file_export_sheet_for_webview(
600→    webview: *mut Object,
601→    file_path: &Path,
602→) -> Result<(), String> {
603→    let controller = ios_top_presenting_view_controller(webview)?;
604→    let path_ns = ns_string(&file_path.to_string_lossy())?;
605→    let url_class = ns_class("NSURL")?;
606→    let url: *mut Object = msg_send![url_class, fileURLWithPath: path_ns];
607→    if url.is_null() {
608→        return Err("Failed to create the iOS export URL.".to_string());
609→    }
610→
611→    let picker_class = ns_class("UIDocumentPickerViewController")?;
612→    let alloc: *mut Object = msg_send![picker_class, alloc];
613→    if alloc.is_null() {
614→        return Err("Failed to allocate the iOS export picker.".to_string());
615→    }
616→
617→    // UIDocumentPickerModeExportToService
618→    let picker: *mut Object = msg_send![alloc, initWithURL: url inMode: 2usize];
619→    if picker.is_null() {
620→        return Err("Failed to initialize the iOS export picker.".to_string());
621→    }
622→
623→    let _: () = msg_send![controller, presentViewController: picker animated: YES completion: ptr::null_mut::<Object>()];
624→    Ok(())
625→}
626→
627→pub(crate) fn present_ios_file_export_sheet(
628→    app: &tauri::AppHandle,
629→    file_path: &Path,
630→) -> Result<(), String> {
631→    if !file_path.is_absolute() {
632→        return Err("Export file path must be absolute.".to_string());
633→    }
634→    if !file_path.exists() || !file_path.is_file() {
635→        return Err(format!(
636→            "Export file not found: {}",
637→            file_path.to_string_lossy()
638→        ));
639→    }
640→
641→    let window = app
642→        .get_webview_window("main")
643→        .ok_or_else(|| "Main window is unavailable for iOS file export.".to_string())?;
644→    let export_path = file_path.to_path_buf();
645→    let (tx, rx) = mpsc::sync_channel(1);
646→
647→    window
648→        .with_webview(move |platform_webview| {
649→            let result = unsafe {
650→                let webview = platform_webview.inner() as *mut Object;
651→                present_ios_file_export_sheet_for_webview(webview, &export_path)
652→            };
653→            let _ = tx.send(result);
654→        })
655→        .map_err(|error| error.to_string())?;
656→
657→    rx.recv()
658→        .map_err(|_| "Failed to receive the iOS export sheet result.".to_string())?
659→}
