159→pub(crate) fn active_transcription_note_paths() -> HashSet<String> {
160→    let queue = transcription_queue_state();
161→    let state = queue.lock().expect("transcription queue poisoned");
162→    let mut active = HashSet::with_capacity(state.pending.len() + 1);
163→    if let Some(current) = &state.current_recording {
164→        active.insert(current.clone());
165→    }
166→    active.extend(state.pending.iter().map(|job| job.note_rel.clone()));
167→    active
168→}
