170→pub(crate) fn recording_queue_snapshot() -> RecordingQueueSnapshot {
171→    let queue = transcription_queue_state();
172→    let state = queue.lock().expect("transcription queue poisoned");
173→    let pending = state
174→        .pending
175→        .iter()
176→        .map(|job| job.note_rel.clone())
177→        .collect::<Vec<_>>();
178→    RecordingQueueSnapshot {
179→        running: state.running,
180→        current_recording: state.current_recording.clone(),
181→        in_flight: pending.len() + usize::from(state.running),
182→        pending,
183→    }
184→}
