188→pub(crate) fn audio_extension_from_mime(mime_type: Option<&str>) -> &'static str {
189→    let Some(raw) = mime_type else {
190→        return "webm";
191→    };
192→    let normalized = raw.to_lowercase();
193→    if normalized.contains("mp4") || normalized.contains("aac") {
194→        return "m4a";
195→    }
196→    if normalized.contains("mpeg") || normalized.contains("mp3") {
197→        return "mp3";
198→    }
199→    if normalized.contains("wav") {
200→        return "wav";
201→    }
202→    if normalized.contains("ogg") {
203→        return "ogg";
204→    }
205→    if normalized.contains("flac") {
206→        return "flac";
207→    }
208→    "webm"
209→}
