211→pub(crate) fn audio_mime_from_path(path: &Path) -> &'static str {
212→    let ext = path
213→        .extension()
214→        .and_then(|value| value.to_str())
215→        .unwrap_or("")
216→        .to_lowercase();
217→    match ext.as_str() {
218→        "m4a" => "audio/mp4",
219→        "mp3" => "audio/mpeg",
220→        "wav" => "audio/wav",
221→        "ogg" => "audio/ogg",
222→        "webm" => "audio/webm",
223→        "aac" => "audio/aac",
224→        "mp4" => "audio/mp4",
225→        "flac" => "audio/flac",
226→        _ => "application/octet-stream",
227→    }
228→}
