252→// ── Note scanning ──────────────────────────────────────────────────────────────
253→
254→fn recording_info_from_note_meta(
255→    root: &Path,
256→    note_path: &Path,
257→    note_rel: &str,
258→    meta: &NoteFrontMatter,
259→) -> Option<RecordingNoteInfo> {
260→    if meta.note_type.as_deref() != Some(RECORDING_FRONTMATTER_TYPE) {
261→        return None;
262→    }
263→    let audio_rel = meta.recording_audio_path.as_ref()?.trim();
264→    if audio_rel.is_empty() {
265→        return None;
266→    }
267→    let audio_rel_path = sanitize_relative(audio_rel).ok()?;
268→    let audio_path = root.join(&audio_rel_path);
269→    if !is_recording_audio_path_allowed(root, &audio_path) {
270→        return None;
271→    }
272→    let status = meta
273→        .transcription_status
274→        .as_deref()
275→        .unwrap_or(RECORDING_STATUS_PENDING)
276→        .to_string();
277→    Some(RecordingNoteInfo {
278→        note_rel: note_rel.to_string(),
279→        note_path: note_path.to_path_buf(),
280→        audio_rel: audio_rel_path.to_string_lossy().replace('\\', "/"),
281→        audio_path,
282→        status,
283→        error: meta.transcription_error.clone(),
284→        updated_ms: meta.transcription_updated_ms.or(meta.updated_ms),
285→    })
286→}
287→
288→/// Scan all markdown notes and extract recording metadata.
289→pub(crate) fn collect_recording_notes(root: &Path) -> Result<Vec<RecordingNoteInfo>, String> {
290→    let mut note_files = Vec::new();
291→    collect_markdown_note_files(root, root, &mut note_files)?;
292→    let mut recordings = Vec::new();
293→    for note_path in note_files {
294→        let raw = match fs::read_to_string(&note_path) {
295→            Ok(value) => value,
296→            Err(_) => continue,
297→        };
298→        let (meta, _) = parse_note_front_matter(&raw);
299→        let note_rel = strip_root(root, &note_path);
300→        if let Some(info) = recording_info_from_note_meta(root, &note_path, &note_rel, &meta) {
301→            recordings.push(info);
302→        }
303→    }
304→    Ok(recordings)
305→}
