307→/// Update a recording note's transcription status and body on disk.
308→pub(crate) fn update_recording_note_status(
309→    note_path: &Path,
310→    status: &str,
311→    error: Option<String>,
312→    transcript_id: Option<String>,
313→    transcript_text: Option<&str>,
314→) -> Result<(), String> {
315→    let raw = fs::read_to_string(note_path).map_err(|issue| issue.to_string())?;
316→    let (mut meta, _) = parse_note_front_matter(&raw);
317→    if meta.id.is_none() {
318→        meta.id = Some(generate_note_id());
319→    }
320→    let now = now_ms();
321→    if meta.created_ms.is_none() {
322→        meta.created_ms = now;
323→    }
324→    meta.updated_ms = now.or(meta.updated_ms);
325→    meta.note_type = Some(RECORDING_FRONTMATTER_TYPE.to_string());
326→    meta.transcription_status = Some(status.to_string());
327→    meta.transcription_error = error.clone();
328→    meta.transcription_updated_ms = now.or(meta.transcription_updated_ms);
329→    meta.transcription_id = transcript_id;
330→    let next_body = recording_note_body(status, transcript_text);
331→    write_note_with_front_matter(note_path, &meta, &next_body)
332→}
