334→// ── AssemblyAI transcription ───────────────────────────────────────────────────
335→
336→fn transcribe_audio_bytes_with_assembly(
337→    audio_bytes: Vec<u8>,
338→    api_key: &str,
339→) -> Result<(String, String), String> {
340→    let client = Client::builder()
341→        .timeout(Duration::from_secs(120))
342→        .build()
343→        .map_err(|error| error.to_string())?;
344→
345→    let upload_response = client
346→        .post(ASSEMBLY_UPLOAD_URL)
347→        .header("authorization", api_key)
348→        .header("content-type", "application/octet-stream")
349→        .body(audio_bytes)
350→        .send()
351→        .map_err(|error| format!("AssemblyAI upload request failed: {}", error))?;
352→    if !upload_response.status().is_success() {
353→        let status = upload_response.status();
354→        let body = upload_response.text().unwrap_or_default();
355→        return Err(response_error(status, body, "AssemblyAI upload"));
356→    }
357→    let upload_payload = upload_response
358→        .json::<AssemblyUploadResponse>()
359→        .map_err(|error| format!("AssemblyAI upload response parse failed: {}", error))?;
360→
361→    let transcript_create_response = client
362→        .post(ASSEMBLY_TRANSCRIPT_URL)
363→        .header("authorization", api_key)
364→        .json(&serde_json::json!({
365→            "audio_url": upload_payload.upload_url,
366→            "speech_models": [ASSEMBLY_SPEECH_MODEL]
367→        }))
368→        .send()
369→        .map_err(|error| format!("AssemblyAI transcript request failed: {}", error))?;
370→    if !transcript_create_response.status().is_success() {
371→        let status = transcript_create_response.status();
372→        let body = transcript_create_response.text().unwrap_or_default();
373→        return Err(response_error(
374→            status,
375→            body,
376→            "AssemblyAI transcript request",
377→        ));
378→    }
379→    let transcript_create_payload = transcript_create_response
380→        .json::<AssemblyTranscriptResponse>()
381→        .map_err(|error| format!("AssemblyAI transcript response parse failed: {}", error))?;
382→    let transcript_id = transcript_create_payload.id;
383→
384→    for _ in 0..ASSEMBLY_MAX_POLL_ATTEMPTS {
385→        thread::sleep(ASSEMBLY_POLL_INTERVAL);
386→        let poll_response = client
387→            .get(format!("{}/{}", ASSEMBLY_TRANSCRIPT_URL, transcript_id))
388→            .header("authorization", api_key)
389→            .send()
390→            .map_err(|error| format!("AssemblyAI polling request failed: {}", error))?;
391→        if !poll_response.status().is_success() {
392→            let status = poll_response.status();
393→            let body = poll_response.text().unwrap_or_default();
394→            return Err(response_error(status, body, "AssemblyAI polling"));
395→        }
396→        let poll_payload = poll_response
397→            .json::<AssemblyTranscriptResponse>()
398→            .map_err(|error| format!("AssemblyAI polling response parse failed: {}", error))?;
399→        match poll_payload.status.as_str() {
400→            "completed" => {
401→                let transcript_text = poll_payload.text.unwrap_or_default();
402→                return Ok((transcript_text, transcript_id));
403→            }
404→            "error" => {
405→                return Err(poll_payload
406→                    .error
407→                    .unwrap_or_else(|| "AssemblyAI reported a transcription error.".to_string()));
408→            }
409→            _ => {}
410→        }
411→    }
412→    Err("AssemblyAI transcription timed out.".to_string())
413→}
