415→// ── Worker ─────────────────────────────────────────────────────────────────────
416→
417→fn process_transcription_job(job: QueuedTranscriptionJob) {
418→    if let Err(error) = update_recording_note_status(
419→        &job.note_path,
420→        RECORDING_STATUS_PROCESSING,
421→        None,
422→        None,
423→        None,
424→    ) {
425→        eprintln!(
426→            "[recordings] failed to mark processing for {}: {}",
427→            job.note_rel, error
428→        );
429→    }
430→
431→    let run = || -> Result<(String, String), String> {
432→        let audio_bytes = fs::read(&job.audio_path).map_err(|error| error.to_string())?;
433→        transcribe_audio_bytes_with_assembly(audio_bytes, &job.api_key)
434→    };
435→
436→    match run() {
437→        Ok((transcript, transcript_id)) => {
438→            if let Err(error) = update_recording_note_status(
439→                &job.note_path,
440→                RECORDING_STATUS_COMPLETED,
441→                None,
442→                Some(transcript_id),
443→                Some(&transcript),
444→            ) {
445→                eprintln!(
446→                    "[recordings] failed to write transcript for {}: {}",
447→                    job.note_rel, error
448→                );
449→            }
450→        }
451→        Err(error) => {
452→            let _ = update_recording_note_status(
453→                &job.note_path,
454→                RECORDING_STATUS_FAILED,
455→                Some(error.clone()),
456→                None,
457→                None,
458→            );
459→            eprintln!(
460→                "[recordings] transcription failed for {}: {}",
461→                job.note_rel, error
462→            );
463→        }
464→    }
465→}
466→
467→/// Start a background worker thread if jobs are queued and none is running.
468→pub(crate) fn spawn_transcription_worker_if_needed() {
469→    let should_spawn = {
470→        let queue = transcription_queue_state();
471→        let mut state = queue.lock().expect("transcription queue poisoned");
472→        if state.running || state.pending.is_empty() {
473→            false
474→        } else {
475→            state.running = true;
476→            true
477→        }
478→    };
479→    if !should_spawn {
480→        return;
481→    }
482→    thread::spawn(move || loop {
483→        let maybe_job = {
484→            let queue = transcription_queue_state();
485→            let mut state = queue.lock().expect("transcription queue poisoned");
486→            match state.pending.pop_front() {
487→                Some(job) => {
488→                    state.current_recording = Some(job.note_rel.clone());
489→                    Some(job)
490→                }
491→                None => {
492→                    state.running = false;
493→                    state.current_recording = None;
494→                    None
495→                }
496→            }
497→        };
498→        let Some(job) = maybe_job else {
499→            break;
500→        };
501→        process_transcription_job(job.clone());
502→        let queue = transcription_queue_state();
503→        let mut state = queue.lock().expect("transcription queue poisoned");
504→        state.known_recordings.remove(&job.note_rel);
505→        if state.current_recording.as_deref() == Some(job.note_rel.as_str()) {
506→            state.current_recording = None;
507→        }
508→    });
509→}
