534→/// Allocate a unique audio file path inside the Recordings storage folder.
535→pub(crate) fn recording_audio_file_path(root: &Path, extension: &str) -> Result<PathBuf, String> {
536→    let storage = recording_storage_root(root);
537→    fs::create_dir_all(&storage).map_err(|error| error.to_string())?;
538→    for _ in 0..=512usize {
539→        let candidate = storage.join(format!(
540→            "{}-{}.{}",
541→            AUDIO_FILE_NAME_PREFIX,
542→            Uuid::now_v7(),
543→            extension
544→        ));
545→        if !candidate.exists() {
546→            return Ok(candidate);
547→        }
548→    }
549→    Err("Failed to allocate recording audio filename.".to_string())
550→}
