552→/// Resolve the target folder for a new recording, falling back to Feed.
553→pub(crate) fn resolve_recording_target_folder(
554→    app: &tauri::AppHandle,
555→    requested: Option<&str>,
556→) -> Result<(String, PathBuf), String> {
557→    let root = notes_root(app)?;
558→    let candidate = requested.unwrap_or("").trim();
559→    if !candidate.is_empty() {
560→        let path = resolve_path(app, candidate)?;
561→        if path.exists() && path.is_dir() && !is_storage_folder_path(&root, &path) {
562→            return Ok((strip_root(&root, &path), path));
563→        }
564→    }
565→    let fallback = root.join(FEED_FOLDER);
566→    Ok((FEED_FOLDER.to_string(), fallback))
567→}
