 58→/// Set window background to transparent at the given alpha level.
 59→#[cfg(target_os = "macos")]
 60→pub(crate) fn apply_macos_window_alpha(
 61→    window: &tauri::WebviewWindow,
 62→    alpha: f64,
 63→) -> tauri::Result<()> {
 64→    use objc::runtime::Object;
 65→    use objc::{class, msg_send, sel, sel_impl};
 66→
 67→    let ns_window = window.ns_window()? as *mut Object;
 68→    unsafe {
 69→        let _: () = msg_send![ns_window, setOpaque: false];
 70→        let ns_color: *mut Object = msg_send![class!(NSColor), clearColor];
 71→        let _: () = msg_send![ns_window, setBackgroundColor: ns_color];
 72→        let _: () = msg_send![ns_window, setAlphaValue: alpha];
 73→    }
 74→    Ok(())
 75→}
