112→/// Decode a base64 data-URI payload, stripping any `data:...;base64,` prefix.
113→pub(crate) fn decode_base64_payload(payload: &str, kind: &str) -> Result<Vec<u8>, String> {
114→    let trimmed = payload.trim();
115→    if trimmed.is_empty() {
116→        return Err(format!("{} payload is empty.", kind));
117→    }
118→    let body = trimmed
119→        .split_once(',')
120→        .map(|(_, value)| value)
121→        .unwrap_or(trimmed);
122→    BASE64
123→        .decode(body)
124→        .map_err(|error| format!("Invalid base64 {} payload: {}", kind.to_lowercase(), error))
125→}
