137→/// Format an HTTP error response with status code and body.
138→pub(crate) fn response_error(status: reqwest::StatusCode, body: String, context: &str) -> String {
139→    let compact = body.replace('\n', " ");
140→    if compact.trim().is_empty() {
141→        format!("{} failed (HTTP {}).", context, status)
142→    } else {
143→        format!("{} failed (HTTP {}): {}", context, status, compact)
144→    }
145→}
