145→/// Resolve the active profile's notes root, creating the directory if needed.
146→pub(crate) fn notes_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
147→    let root = match ensure_profiles_state(app) {
148→        Ok(state) => {
149→            let active = find_profile(&state, &state.active_profile_id)
150→                .or_else(|| state.profiles.first())
151→                .ok_or_else(|| "No profiles configured.".to_string())?;
152→            PathBuf::from(&active.notes_root)
153→        }
154→        Err(_) => crate::legacy_notes_root(app)?,
155→    };
156→    if !root.exists() {
157→        fs::create_dir_all(&root).map_err(|err| err.to_string())?;
158→    }
159→    Ok(root)
