171→/// Reject absolute paths and parent-dir traversals.
172→pub(crate) fn sanitize_relative(path: &str) -> Result<PathBuf, String> {
173→    if path.is_empty() {
174→        return Ok(PathBuf::new());
175→    }
176→    let candidate = Path::new(path);
177→    if candidate.is_absolute() {
178→        return Err("Absolute paths are not allowed.".to_string());
179→    }
180→    for component in candidate.components() {
181→        match component {
182→            Component::ParentDir | Component::RootDir | Component::Prefix(_) => {
183→                return Err("Invalid path traversal.".to_string())
184→            }
185→            _ => {}
186→        }
187→    }
188→    Ok(candidate.to_path_buf())
189→}
190→
191→/// Join a sanitized relative path onto the notes root.
192→pub(crate) fn resolve_path(app: &tauri::AppHandle, rel: &str) -> Result<PathBuf, String> {
193→    let root = notes_root(app)?;
194→    let rel_path = sanitize_relative(rel)?;
195→    Ok(root.join(rel_path))
196→}
