207→
208→/// Parse `---` delimited YAML-ish front-matter from a raw markdown string.
209→pub(crate) fn parse_note_front_matter(raw: &str) -> (NoteFrontMatter, String) {
210→    let mut meta = NoteFrontMatter::default();
211→    let normalized = raw.replace("\r\n", "\n");
212→    if !normalized.starts_with("---\n") {
213→        return (meta, raw.to_string());
214→    }
215→    let Some(close_marker_index) = normalized[4..].find("\n---\n") else {
216→        return (meta, raw.to_string());
217→    };
218→    let header_end = 4 + close_marker_index;
219→    let header = &normalized[4..header_end];
220→    let body = &normalized[(header_end + 5)..];
221→
222→    for line in header.lines() {
223→        let trimmed = line.trim();
224→        if trimmed.is_empty() {
225→            continue;
226→        }
227→        let Some((key_raw, value_raw)) = trimmed.split_once(':') else {
228→            meta.passthrough_lines.push(trimmed.to_string());
229→            continue;
230→        };
231→        let key = key_raw.trim().to_lowercase();
232→        let value = value_raw
233→            .trim()
234→            .trim_matches('"')
235→            .trim_matches('\'')
236→            .to_string();
237→        match key.as_str() {
238→            "id" => {
239→                if !value.is_empty() {
240→                    meta.id = Some(value);
241→                }
242→            }
243→            "created_ms" => {
244→                if let Ok(parsed) = value.parse::<i64>() {
245→                    meta.created_ms = Some(parsed);
246→                } else {
247→                    meta.passthrough_lines.push(trimmed.to_string());
248→                }
249→            }
250→            "updated_ms" => {
251→                if let Ok(parsed) = value.parse::<i64>() {
252→                    meta.updated_ms = Some(parsed);
253→                } else {
254→                    meta.passthrough_lines.push(trimmed.to_string());
255→                }
256→            }
257→            "type" => {
258→                if !value.is_empty() {
259→                    meta.note_type = Some(value);
260→                }
261→            }
262→            "recording_audio_path" => {
263→                if !value.is_empty() {
264→                    meta.recording_audio_path = Some(value);
265→                }
266→            }
267→            "handwriting_attachment_path" => {
268→                if !value.is_empty() {
269→                    meta.handwriting_attachment_path = Some(value);
270→                }
271→            }
272→            "transcription_status" => {
273→                if !value.is_empty() {
274→                    meta.transcription_status = Some(value);
275→                }
276→            }
277→            "transcription_error" => {
278→                if !value.is_empty() {
279→                    meta.transcription_error = Some(value);
280→                }
281→            }
282→            "transcription_updated_ms" => {
283→                if let Ok(parsed) = value.parse::<i64>() {
284→                    meta.transcription_updated_ms = Some(parsed);
285→                } else {
286→                    meta.passthrough_lines.push(trimmed.to_string());
287→                }
288→            }
289→            "transcription_id" => {
290→                if !value.is_empty() {
291→                    meta.transcription_id = Some(value);
292→                }
293→            }
294→            "ocr_status" => {
295→                if !value.is_empty() {
296→                    meta.ocr_status = Some(value);
297→                }
298→            }
299→            "ocr_error" => {
300→                if !value.is_empty() {
301→                    meta.ocr_error = Some(value);
302→                }
303→            }
304→            "ocr_updated_ms" => {
305→                if let Ok(parsed) = value.parse::<i64>() {
306→                    meta.ocr_updated_ms = Some(parsed);
307→                } else {
308→                    meta.passthrough_lines.push(trimmed.to_string());
309→                }
310→            }
311→            _ => meta.passthrough_lines.push(trimmed.to_string()),
312→        }
313→    }
314→
315→    (meta, body.to_string())
316→}
