318→/// Escape a front-matter value if it contains special characters.
319→fn front_matter_safe_value(value: &str) -> String {
320→    if value
321→        .chars()
322→        .all(|char| char.is_ascii_alphanumeric() || matches!(char, '-' | '_' | '.'))
323→    {
324→        value.to_string()
325→    } else {
326→        format!("{:?}", value)
327→    }
328→}
