256→// ── Ahead / behind ─────────────────────────────────────────────────────────────
257→
258→fn git_ahead_behind(repo: &Repository, branch: Option<&str>) -> (usize, usize) {
259→    let branch_name = match branch {
260→        Some(value) => value,
261→        None => return (0, 0),
262→    };
263→    let local = match repo.find_branch(branch_name, git2::BranchType::Local) {
264→        Ok(branch) => branch,
265→        Err(_) => return (0, 0),
266→    };
267→    let upstream = match local.upstream() {
268→        Ok(branch) => branch,
269→        Err(_) => return (0, 0),
270→    };
271→    let local_oid = match local.get().target() {
272→        Some(value) => value,
273→        None => return (0, 0),
274→    };
275→    let upstream_oid = match upstream.get().target() {
276→        Some(value) => value,
277→        None => return (0, 0),
278→    };
279→    repo.graph_ahead_behind(local_oid, upstream_oid)
280→        .unwrap_or((0, 0))
281→}
282→
283→fn git_branch_has_local_commit(repo: &Repository, branch: Option<&str>) -> bool {
284→    let Some(branch_name) = branch else {
285→        return false;
286→    };
287→    repo.find_branch(branch_name, git2::BranchType::Local)
288→        .ok()
289→        .and_then(|branch_ref| branch_ref.get().target())
290→        .is_some()
291→}
292→
293→fn git_branch_has_upstream(repo: &Repository, branch: Option<&str>) -> bool {
294→    let Some(branch_name) = branch else {
295→        return false;
296→    };
297→    repo.find_branch(branch_name, git2::BranchType::Local)
298→        .ok()
299→        .and_then(|branch_ref| branch_ref.upstream().ok())
300→        .is_some()
301→}
