303→// ── Status & history ───────────────────────────────────────────────────────────
304→
305→/// Build a comprehensive git sync status snapshot for the frontend.
306→pub(crate) fn build_git_status(root: &Path) -> GitSyncStatus {
307→    let repo = Repository::open(root).ok();
308→    let repo_initialized = repo.is_some();
309→    let current_branch = repo.as_ref().and_then(git_current_branch);
310→    let remote_url = repo.as_ref().and_then(git_remote_url);
311→    let has_uncommitted_changes = repo.as_ref().is_some_and(git_has_changes);
312→    let (ahead, behind) = repo
313→        .as_ref()
314→        .map(|repository| git_ahead_behind(repository, current_branch.as_deref()))
315→        .unwrap_or((0, 0));
316→    let push_required = repo
317→        .as_ref()
318→        .map(|repository| {
319→            if has_uncommitted_changes || ahead > 0 {
320→                return true;
321→            }
322→            let branch = current_branch.as_deref();
323→            let has_local_commit = git_branch_has_local_commit(repository, branch);
324→            let has_upstream = git_branch_has_upstream(repository, branch);
325→            has_local_commit && !has_upstream
326→        })
327→        .unwrap_or(false);
328→    GitSyncStatus {
329→        git_available: true,
330→        repo_initialized,
331→        current_branch,
332→        remote_url,
333→        has_uncommitted_changes,
334→        push_required,
335→        ahead,
336→        behind,
337→        notes_root: root.to_string_lossy().to_string(),
338→    }
339→}
340→
341→fn git_upstream_oid(repo: &Repository, branch: Option<&str>) -> Option<Oid> {
342→    let branch_name = branch?;
343→    repo.find_branch(branch_name, git2::BranchType::Local)
344→        .ok()
345→        .and_then(|local| local.upstream().ok())
346→        .and_then(|upstream| upstream.get().target())
347→}
348→
349→/// Build the commit history list with sync state indicators.
350→pub(crate) fn build_git_history(
351→    root: &Path,
352→    limit: usize,
353→) -> Result<Vec<GitCommitHistoryEntry>, String> {
354→    if !git_repo_initialized(root) {
355→        return Ok(Vec::new());
356→    }
357→    let repo = open_repo(root)?;
358→    let head_oid = match repo.head().ok().and_then(|head| head.target()) {
359→        Some(oid) => oid,
360→        None => return Ok(Vec::new()),
361→    };
362→    let branch = git_current_branch(&repo);
363→    let upstream_oid = git_upstream_oid(&repo, branch.as_deref());
364→
365→    let mut revwalk = repo.revwalk().map_err(map_git_error)?;
366→    revwalk
367→        .set_sorting(Sort::TOPOLOGICAL | Sort::TIME)
368→        .map_err(map_git_error)?;
369→    revwalk.push(head_oid).map_err(map_git_error)?;
370→
371→    let mut entries = Vec::new();
372→    let max_items = limit.clamp(1, 200);
373→    for oid_result in revwalk.take(max_items) {
374→        let oid = oid_result.map_err(map_git_error)?;
375→        let commit = repo.find_commit(oid).map_err(map_git_error)?;
376→        let summary = commit
377→            .summary()
378→            .map(str::trim)
379→            .filter(|value| !value.is_empty())
380→            .unwrap_or("No commit message")
381→            .to_string();
382→        let author_signature = commit.author();
383→        let author = author_signature
384→            .name()
385→            .or_else(|| author_signature.email())
386→            .map(str::trim)
387→            .filter(|value| !value.is_empty())
388→            .unwrap_or("Unknown author")
389→            .to_string();
390→        let authored_ms = commit.time().seconds().checked_mul(1_000);
391→        let sync_state = if let Some(upstream) = upstream_oid {
392→            if oid == upstream || repo.graph_descendant_of(upstream, oid).unwrap_or(false) {
393→                "synced"
394→            } else {
395→                "local"
396→            }
397→        } else {
398→            "local"
399→        };
400→        let id = oid.to_string();
401→        let short_id = id.chars().take(8).collect::<String>();
402→        entries.push(GitCommitHistoryEntry {
403→            id,
404→            short_id,
405→            summary,
406→            author,
407→            authored_ms,
408→            sync_state: sync_state.to_string(),
409→            is_head: oid == head_oid,
410→        });
411→    }
412→    Ok(entries)
413→}
