472→pub(crate) fn ensure_origin_remote(repo: &Repository, remote_url: &str) -> Result<(), String> {
473→    let url = remote_url.trim();
474→    if url.is_empty() {
475→        return Err("Remote repository URL is required.".to_string());
476→    }
477→    match repo.find_remote("origin") {
478→        Ok(_) => repo.remote_set_url("origin", url).map_err(map_git_error)?,
479→        Err(_) => {
480→            repo.remote("origin", url).map_err(map_git_error)?;
481→        }
482→    }
483→    Ok(())
484→}
485→
486→pub(crate) fn switch_or_prepare_branch(repo: &Repository, branch: &str) -> Result<(), String> {
487→    let name = branch.trim();
488→    if name.is_empty() {
489→        return Ok(());
490→    }
491→    let local_ref = format!("refs/heads/{}", name);
492→    if repo.find_reference(&local_ref).is_ok() {
493→        repo.set_head(&local_ref).map_err(map_git_error)?;
494→        repo.checkout_head(Some(CheckoutBuilder::new().safe()))
495→            .map_err(map_git_error)?;
496→        return Ok(());
497→    }
498→    if let Ok(head) = repo.head() {
499→        if let Some(head_oid) = head.target() {
500→            let commit = repo.find_commit(head_oid).map_err(map_git_error)?;
501→            repo.branch(name, &commit, false).map_err(map_git_error)?;
502→            repo.set_head(&local_ref).map_err(map_git_error)?;
503→            repo.checkout_head(Some(CheckoutBuilder::new().safe()))
504→                .map_err(map_git_error)?;
505→            return Ok(());
506→        }
507→    }
508→    repo.set_head(&local_ref).map_err(map_git_error)
509→}
510→
511→fn default_signature(repo: &Repository) -> Result<Signature<'_>, String> {
512→    if let Ok(sig) = repo.signature() {
513→        return Ok(sig);
514→    }
515→    Signature::now("Type Notes Sync", "sync@local").map_err(map_git_error)
516→}
517→
518→/// Stage all changes and create a commit on the given branch.
519→pub(crate) fn commit_all_changes(
520→    repo: &Repository,
521→    message: &str,
522→    branch: &str,
523→) -> Result<Option<Oid>, String> {
524→    let mut index = repo.index().map_err(map_git_error)?;
525→    index
526→        .add_all(["*"].iter(), IndexAddOption::DEFAULT, None)
527→        .map_err(map_git_error)?;
528→    index.write().map_err(map_git_error)?;
529→    if index.is_empty() && !git_has_changes(repo) {
530→        return Ok(None);
531→    }
532→    let tree_id = index.write_tree().map_err(map_git_error)?;
533→    let tree = repo.find_tree(tree_id).map_err(map_git_error)?;
534→    let sig = default_signature(repo)?;
535→    let update_ref = format!("refs/heads/{}", branch);
536→    let oid = match repo.head() {
537→        Ok(head) => {
538→            if let Some(head_oid) = head.target() {
539→                let parent = repo.find_commit(head_oid).map_err(map_git_error)?;
540→                repo.commit(Some(&update_ref), &sig, &sig, message, &tree, &[&parent])
541→                    .map_err(map_git_error)?
542→            } else {
543→                repo.commit(Some(&update_ref), &sig, &sig, message, &tree, &[])
544→                    .map_err(map_git_error)?
545→            }
546→        }
547→        Err(_) => repo
548→            .commit(Some(&update_ref), &sig, &sig, message, &tree, &[])
549→            .map_err(map_git_error)?,
550→    };
551→    repo.set_head(&update_ref).map_err(map_git_error)?;
552→    Ok(Some(oid))
553→}
554→
555→// ── Fetch / merge ──────────────────────────────────────────────────────────────
556→
557→pub(crate) fn perform_fetch<'a>(
558→    repo: &'a Repository,
559→    branch: &str,
560→    username: Option<&str>,
561→    password: Option<&str>,
562→) -> Result<AnnotatedCommit<'a>, String> {
563→    let mut remote = repo.find_remote("origin").map_err(map_git_error)?;
564→    let callbacks = build_callbacks(username, password);
565→    let mut fetch_options = FetchOptions::new();
566→    fetch_options.remote_callbacks(callbacks);
567→    remote
568→        .fetch(&[branch], Some(&mut fetch_options), None)
569→        .map_err(map_git_error)?;
570→    let fetch_head = repo.find_reference("FETCH_HEAD").map_err(map_git_error)?;
571→    repo.reference_to_annotated_commit(&fetch_head)
572→        .map_err(map_git_error)
573→}
574→
575→pub(crate) fn fast_forward_to(
576→    repo: &Repository,
577→    branch: &str,
578→    fetch_commit: &AnnotatedCommit<'_>,
579→) -> Result<(), String> {
580→    let target_oid = fetch_commit.id();
581→    let local_ref_name = format!("refs/heads/{}", branch);
582→    match repo.find_reference(&local_ref_name) {
583→        Ok(mut local_ref) => {
584→            local_ref
585→                .set_target(target_oid, "Fast-forward")
586→                .map_err(map_git_error)?;
587→            repo.set_head(&local_ref_name).map_err(map_git_error)?;
588→            repo.checkout_head(Some(CheckoutBuilder::new().safe()))
589→                .map_err(map_git_error)?;
590→        }
591→        Err(_) => {
592→            let commit = repo.find_commit(target_oid).map_err(map_git_error)?;
593→            repo.branch(branch, &commit, false).map_err(map_git_error)?;
594→            repo.set_head(&local_ref_name).map_err(map_git_error)?;
595→            repo.checkout_head(Some(CheckoutBuilder::new().safe()))
596→                .map_err(map_git_error)?;
597→        }
598→    }
599→    Ok(())
600→}
601→
602→/// Merge a fetched commit, rolling back on conflict.
603→pub(crate) fn merge_fetched_commit(
604→    repo: &Repository,
605→    branch: &str,
606→    fetched_commit: &AnnotatedCommit<'_>,
607→) -> Result<(), String> {
608→    let pre_merge_head = repo
609→        .head()
610→        .map_err(map_git_error)?
611→        .peel_to_commit()
612→        .map_err(map_git_error)?;
613→
614→    let mut checkout_options = CheckoutBuilder::new();
615→    checkout_options.safe();
616→    repo.merge(&[fetched_commit], None, Some(&mut checkout_options))
617→        .map_err(map_git_error)?;
618→
619→    let merge_result = (|| -> Result<(), String> {
620→        let head_commit = repo
621→            .head()
622→            .map_err(map_git_error)?
623→            .peel_to_commit()
624→            .map_err(map_git_error)?;
625→        let remote_commit = repo
626→            .find_commit(fetched_commit.id())
627→            .map_err(map_git_error)?;
628→        let mut index = repo.index().map_err(map_git_error)?;
629→        if index.has_conflicts() {
630→            let mut paths = Vec::new();
631→            if let Ok(conflicts) = index.conflicts() {
632→                for entry in conflicts.flatten() {
633→                    let path_bytes = entry
634→                        .our
635→                        .as_ref()
636→                        .and_then(|value| std::str::from_utf8(&value.path).ok())
637→                        .or_else(|| {
638→                            entry
639→                                .their
640→                                .as_ref()
641→                                .and_then(|value| std::str::from_utf8(&value.path).ok())
642→                        })
643→                        .or_else(|| {
644→                            entry
645→                                .ancestor
646→                                .as_ref()
647→                                .and_then(|value| std::str::from_utf8(&value.path).ok())
648→                        });
649→                    if let Some(path) = path_bytes {
650→                        paths.push(path.to_string());
651→                    }
652→                }
653→            }
654→            paths.sort();
655→            paths.dedup();
656→            let details = if paths.is_empty() {
657→                String::new()
658→            } else {
659→                format!(" ({})", paths.join(", "))
660→            };
661→            return Err(
662→                format!(
663→                    "Pull produced merge conflicts{}. Resolve conflicts on desktop, then pull again on mobile.",
664→                    details
665→                ),
666→            );
667→        }
668→        let tree_id = index.write_tree_to(repo).map_err(map_git_error)?;
669→        let tree = repo.find_tree(tree_id).map_err(map_git_error)?;
670→        let signature = default_signature(repo)?;
671→        let message = format!("Merge origin/{branch} into {branch}");
672→        repo.commit(
673→            Some("HEAD"),
674→            &signature,
675→            &signature,
676→            &message,
677→            &tree,
678→            &[&head_commit, &remote_commit],
679→        )
680→        .map_err(map_git_error)?;
681→        repo.checkout_head(Some(CheckoutBuilder::new().safe()))
682→            .map_err(map_git_error)?;
683→        Ok(())
684→    })();
685→
686→    match merge_result {
687→        Ok(()) => {
688→            repo.cleanup_state().map_err(map_git_error)?;
689→            Ok(())
690→        }
691→        Err(error_message) => {
692→            let cleanup_error = repo.cleanup_state().map_err(map_git_error).err();
693→            let reset_error = repo
694→                .reset(pre_merge_head.as_object(), ResetType::Hard, None)
695→                .map_err(map_git_error)
696→                .err();
697→            if cleanup_error.is_none() && reset_error.is_none() {
698→                return Err(error_message);
699→            }
700→            let mut extras = Vec::new();
701→            if let Some(value) = cleanup_error {
702→                extras.push(format!("cleanup_state failed: {value}"));
703→            }
704→            if let Some(value) = reset_error {
705→                extras.push(format!("reset failed: {value}"));
706→            }
707→            Err(format!(
708→                "{error_message} Automatic rollback failed: {}",
709→                extras.join("; ")
710→            ))
711→        }
712→    }
713→}
