196→fn connect_git_repo_blocking(
197→    app: tauri::AppHandle,
198→    args: ConnectGitArgs,
199→) -> Result<GitSyncStatus, String> {
200→    ensure_security_unlocked_for_app(&app)?;
201→    let root = ensured_notes_root(&app)?;
202→    let repo = ensure_git_repo(&root)?;
203→    prepare_bootstrap_worktree_for_sync(&root, &repo)?;
204→    ensure_origin_remote(&repo, &args.remote_url)?;
205→    let target_branch = resolve_target_branch(&repo, args.branch.clone());
206→    switch_or_prepare_branch(&repo, &target_branch)?;
207→    let fetched = match perform_fetch(
208→        &repo,
209→        &target_branch,
210→        args.username.as_deref(),
211→        args.password.as_deref(),
212→    ) {
213→        Ok(commit) => Some(commit),
214→        Err(error) => {
215→            let lower = error.to_lowercase();
216→            if lower.contains("couldn't find remote ref") {
217→                None
218→            } else {
219→                return Err(error);
220→            }
221→        }
222→    };
223→    if let Some(fetched_commit) = fetched {
224→        let analysis = repo
225→            .merge_analysis(&[&fetched_commit])
226→            .map_err(map_git_error)?
227→            .0;
228→        if analysis.is_fast_forward() || analysis.is_up_to_date() {
229→            fast_forward_to(&repo, &target_branch, &fetched_commit)?;
230→        }
231→    }
232→    Ok(build_git_status(&root))
233→}
