241→fn git_pull_blocking(app: tauri::AppHandle, args: GitSyncArgs) -> Result<GitSyncStatus, String> {
242→    ensure_security_unlocked_for_app(&app)?;
243→    let root = ensured_notes_root(&app)?;
244→    if !git_repo_initialized(&root) {
245→        return Err("Repository is not initialized. Connect a remote first.".to_string());
246→    }
247→    let repo = open_repo(&root)?;
248→    prepare_bootstrap_worktree_for_sync(&root, &repo)?;
249→    if git_has_changes(&repo) {
250→        return Err("Local changes detected. Push or commit before pulling.".to_string());
251→    }
252→    let target_branch = resolve_target_branch(&repo, args.branch.clone());
253→    switch_or_prepare_branch(&repo, &target_branch)?;
254→    let fetched = perform_fetch(
255→        &repo,
256→        &target_branch,
257→        args.username.as_deref(),
258→        args.password.as_deref(),
259→    )?;
260→    let (analysis, _) = repo.merge_analysis(&[&fetched]).map_err(map_git_error)?;
261→    if analysis.is_up_to_date() {
262→        return Ok(build_git_status(&root));
263→    }
264→    if analysis.is_fast_forward() {
265→        fast_forward_to(&repo, &target_branch, &fetched)?;
266→        return Ok(build_git_status(&root));
267→    }
268→    if analysis.is_normal() {
269→        merge_fetched_commit(&repo, &target_branch, &fetched)?;
270→        return Ok(build_git_status(&root));
271→    }
272→    Err("Pull failed because local and remote history could not be merged.".to_string())
273→}
