 81→/// Resolve the app-data directory, creating it if absent.
 82→pub(crate) fn app_data_dir(app: &tauri::AppHandle) -> Result<PathBuf, String> {
 83→    let path = app.path().app_data_dir().map_err(|err| err.to_string())?;
