  1→import {
  2→  createContext,
  3→  useCallback,
  4→  useContext,
  5→  useEffect,
  6→  useState,
  7→  type ReactNode,
  8→} from "react";
  9→import * as api from "../data/gitApi";
 10→import type {
 11→  GitCommitHistoryEntry,
 12→  GitSyncAction,
 13→  GitSyncStatus,
 14→} from "../types";
 15→import { yieldToUi } from "../utils/notes";
 16→import { useProfiles } from "./ProfilesContext";
 17→import { useLayoutMode } from "../mobile/useLayoutMode";
 18→
 19→type GitSyncContextValue = {
 20→  gitStatus: GitSyncStatus | null;
 21→  gitSyncAction: GitSyncAction;
 22→  gitSyncError: string | null;
 23→  gitSyncBusy: boolean;
 24→  gitCommitHistory: GitCommitHistoryEntry[];
 25→  gitHistoryBusy: boolean;
 26→  gitHistoryError: string | null;
 27→  refreshGitStatus: () => Promise<void>;
 28→  refreshGitHistory: (limit?: number) => Promise<void>;
 29→  connectGitRepo: () => Promise<void>;
 30→  gitPull: (opts?: { onAfterPull?: () => Promise<void> }) => Promise<void>;
 31→  gitPush: () => Promise<void>;
 32→  setGitStatus: (status: GitSyncStatus | null) => void;
 33→  setGitSyncError: (error: string | null) => void;
 34→};
 35→
 36→const GitSyncContext = createContext<GitSyncContextValue | null>(null);
 37→
 38→export function GitSyncProvider({ children }: { children: ReactNode }) {
 39→  const { activeProfileId, syncSettings, updateSyncSettings } = useProfiles();
 40→  const layoutMode = useLayoutMode();
 41→  const [gitStatus, setGitStatus] = useState<GitSyncStatus | null>(null);
 42→  const [gitSyncAction, setGitSyncAction] = useState<GitSyncAction>("idle");
 43→  const [gitSyncError, setGitSyncError] = useState<string | null>(null);
 44→  const [gitCommitHistory, setGitCommitHistory] = useState<GitCommitHistoryEntry[]>([]);
 45→  const [gitHistoryBusy, setGitHistoryBusy] = useState(false);
 46→  const [gitHistoryError, setGitHistoryError] = useState<string | null>(null);
 47→
 48→  const gitSyncBusy = gitSyncAction !== "idle";
 49→
 50→  const refreshGitStatus = useCallback(async () => {
 51→    setGitSyncAction("refresh");
 52→    await yieldToUi();
 53→    try {
 54→      const status = await api.getGitStatus();
 55→      setGitStatus(status);
 56→      setGitSyncError(null);
 57→    } catch (error) {
 58→      const message = error instanceof Error ? error.message : String(error);
 59→      setGitSyncError(message);
 60→    } finally {
 61→      setGitSyncAction("idle");
 62→    }
 63→  }, []);
 64→
 65→  const refreshGitHistory = useCallback(async (limit = 40) => {
 66→    setGitHistoryBusy(true);
 67→    await yieldToUi();
 68→    try {
 69→      const history = await api.getGitHistory(limit);
 70→      setGitCommitHistory(history);
 71→      setGitHistoryError(null);
 72→    } catch (error) {
 73→      const message = error instanceof Error ? error.message : String(error);
 74→      setGitHistoryError(message);
 75→      setGitCommitHistory([]);
 76→    } finally {
 77→      setGitHistoryBusy(false);
 78→    }
 79→  }, []);
 80→
 81→  useEffect(() => {
 82→    if (!activeProfileId) {
 83→      setGitStatus(null);
 84→      setGitSyncError(null);
 85→      setGitCommitHistory([]);
 86→      setGitHistoryError(null);
 87→      return;
 88→    }
 89→    if (layoutMode === "phone") {
 90→      return;
 91→    }
 92→    void refreshGitStatus();
 93→    void refreshGitHistory();
 94→  }, [activeProfileId, layoutMode, refreshGitHistory, refreshGitStatus]);
 95→
 96→  useEffect(() => {
 97→    if (!activeProfileId || !gitStatus?.repo_initialized) {
 98→      return;
 99→    }
100→    const patch: Partial<typeof syncSettings> = {};
101→    if (!syncSettings.gitRemoteUrl.trim() && gitStatus.remote_url) {
102→      patch.gitRemoteUrl = gitStatus.remote_url;
103→    }
104→    if (!syncSettings.gitBranch.trim() && gitStatus.current_branch) {
105→      patch.gitBranch = gitStatus.current_branch;
106→    }
107→    if (Object.keys(patch).length > 0) {
108→      updateSyncSettings(patch);
109→    }
110→  }, [
111→    activeProfileId,
112→    gitStatus,
113→    syncSettings.gitBranch,
114→    syncSettings.gitRemoteUrl,
115→    updateSyncSettings,
116→  ]);
117→
118→  const connectGitRepo = useCallback(async () => {
119→    const remoteUrl = syncSettings.gitRemoteUrl.trim();
120→    const branch = syncSettings.gitBranch.trim();
121→    if (!remoteUrl) {
122→      setGitSyncError("Remote repository URL is required.");
123→      return;
124→    }
125→    setGitSyncAction("connect");
126→    await yieldToUi();
127→    try {
128→      const status = await api.connectGitRepo(
129→        remoteUrl,
130→        branch || undefined,
131→        syncSettings.gitUsername.trim() || undefined,
132→        syncSettings.gitPassword || undefined
133→      );
134→      setGitStatus(status);
135→      setGitSyncError(null);
136→      void refreshGitHistory();
137→    } catch (error) {
138→      const message = error instanceof Error ? error.message : String(error);
139→      setGitSyncError(message);
140→    } finally {
141→      setGitSyncAction("idle");
142→    }
143→  }, [refreshGitHistory, syncSettings]);
144→
145→  const gitPull = useCallback(
146→    async (opts?: { onAfterPull?: () => Promise<void> }) => {
147→      const branch = syncSettings.gitBranch.trim();
148→      setGitSyncAction("pull");
149→      await yieldToUi();
150→      try {
151→        const status = await api.gitPull(
152→          branch || undefined,
153→          syncSettings.gitUsername.trim() || undefined,
154→          syncSettings.gitPassword || undefined
155→        );
156→        setGitStatus(status);
157→        setGitSyncError(null);
158→        updateSyncSettings({ lastSuccessfulSyncAt: new Date().toISOString() });
159→        void refreshGitHistory();
160→        if (opts?.onAfterPull) {
161→          await opts.onAfterPull();
162→        }
163→      } catch (error) {
164→        const message = error instanceof Error ? error.message : String(error);
165→        setGitSyncError(message);
166→      } finally {
167→        setGitSyncAction("idle");
168→      }
169→    },
170→    [refreshGitHistory, syncSettings, updateSyncSettings]
171→  );
172→
173→  const gitPush = useCallback(async () => {
174→    const branch = syncSettings.gitBranch.trim();
175→    const commitMessage = syncSettings.gitCommitMessage.trim();
176→    setGitSyncAction("push");
177→    await yieldToUi();
178→    try {
179→      const statusBeforePush = await api.getGitStatus();
180→      setGitStatus(statusBeforePush);
181→      if (!statusBeforePush.push_required) {
182→        setGitSyncError(null);
183→        void refreshGitHistory();
184→        return;
185→      }
186→      const status = await api.gitPush(
187→        commitMessage || undefined,
188→        branch || undefined,
189→        syncSettings.gitUsername.trim() || undefined,
190→        syncSettings.gitPassword || undefined
191→      );
192→      setGitStatus(status);
193→      setGitSyncError(null);
194→      updateSyncSettings({ lastSuccessfulSyncAt: new Date().toISOString() });
195→      void refreshGitHistory();
196→    } catch (error) {
197→      const message = error instanceof Error ? error.message : String(error);
198→      setGitSyncError(message);
199→    } finally {
200→      setGitSyncAction("idle");
201→    }
202→  }, [refreshGitHistory, syncSettings, updateSyncSettings]);
203→
204→  return (
205→    <GitSyncContext.Provider
206→      value={{
207→        gitStatus,
208→        gitSyncAction,
209→        gitSyncError,
210→        gitSyncBusy,
211→        gitCommitHistory,
212→        gitHistoryBusy,
213→        gitHistoryError,
214→        refreshGitStatus,
215→        refreshGitHistory,
216→        connectGitRepo,
217→        gitPull,
218→        gitPush,
219→        setGitStatus,
220→        setGitSyncError,
221→      }}
222→    >
223→      {children}
224→    </GitSyncContext.Provider>
225→  );
226→}
227→
228→export function useGitSync() {
229→  const context = useContext(GitSyncContext);
230→  if (!context) {
231→    throw new Error("useGitSync must be used within a GitSyncProvider");
232→  }
233→  return context;
234→}
