 19→type ProfilesContextValue = {
 20→  profilesSnapshot: NotesProfileSnapshot | null;
 21→  profilesBusy: boolean;
 22→  profilesError: string | null;
 23→  profiles: NotesProfileSnapshot["profiles"];
 24→  activeProfileId: string | null;
 25→  activeProfileNotesRoot: string | null;
 26→  syncSettings: ProfileSyncSettings;
 27→  updateSyncSettings: (patch: Partial<ProfileSyncSettings>) => void;
 28→  refreshProfiles: () => Promise<NotesProfileSnapshot>;
 29→  switchProfile: (profileId: string) => Promise<void>;
 30→  createProfile: (input?: { name?: string; description?: string }) => Promise<void>;
 31→  updateProfile: (
 32→    profileId: string,
 33→    patch: { name?: string; description?: string }
 34→  ) => Promise<void>;
 35→  deleteProfile: (profileId: string) => Promise<void>;
 36→  setProfileNotesRoot: (profileId: string, notesRoot: string) => Promise<void>;
 37→  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
 38→};
 39→
 40→const ProfilesContext = createContext<ProfilesContextValue | null>(null);
 41→
 42→export function ProfilesProvider({
 43→  children,
 44→  flushSaveRef,
 45→}: {
 46→  children: ReactNode;
 47→  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
 48→}) {
 49→  const [profilesSnapshot, setProfilesSnapshot] = useState<NotesProfileSnapshot | null>(null);
 50→  const [profilesBusy, setProfilesBusy] = useState(false);
 51→  const [profilesError, setProfilesError] = useState<string | null>(null);
 52→  const [syncSettings, setSyncSettings] = useState<ProfileSyncSettings>(DEFAULT_PROFILE_SYNC_SETTINGS);
 53→  const [syncSettingsProfileId, setSyncSettingsProfileId] = useState<string | null>(null);
 54→
 55→  const profiles = profilesSnapshot?.profiles ?? [];
 56→  const activeProfileId = profilesSnapshot?.activeProfileId ?? null;
 57→  const activeProfileNotesRoot =
 58→    profiles.find((profile) => profile.id === activeProfileId)?.notes_root ?? null;
 59→
 60→  const refreshProfiles = useCallback(async () => {
 61→    const snapshot = await api.getProfiles();
 62→    setProfilesSnapshot(snapshot);
 63→    return snapshot;
 64→  }, []);
 65→
 66→  const updateSyncSettings = useCallback((patch: Partial<ProfileSyncSettings>) => {
 67→    setSyncSettings((prev) => ({ ...prev, ...patch }));
 68→  }, []);
 69→
 70→  // Load sync settings when active profile changes
 71→  useEffect(() => {
 72→    if (!activeProfileId) {
 73→      return;
 74→    }
 75→    const settings = getProfileSyncSettings(activeProfileId);
 76→    setSyncSettings(settings);
 77→    setSyncSettingsProfileId(activeProfileId);
 78→  }, [activeProfileId]);
 79→
 80→  // Persist sync settings when they change
 81→  useEffect(() => {
 82→    if (!activeProfileId || syncSettingsProfileId !== activeProfileId) {
 83→      return;
 84→    }
 85→    const store = readProfileSyncStore();
 86→    store[activeProfileId] = syncSettings;
 87→    writeProfileSyncStore(store);
 88→  }, [activeProfileId, syncSettings, syncSettingsProfileId]);
 89→
 90→  // Initial fetch
 91→  useEffect(() => {
 92→    void (async () => {
 93→      setProfilesBusy(true);
 94→      try {
 95→        await refreshProfiles();
 96→        setProfilesError(null);
 97→      } catch (error) {
 98→        const message = error instanceof Error ? error.message : String(error);
 99→        setProfilesError(message);
100→      } finally {
101→        setProfilesBusy(false);
102→      }
103→    })();
104→  }, [refreshProfiles]);
105→
106→  const switchProfile = useCallback(
107→    async (profileId: string) => {
108→      const normalizedId = profileId.trim();
109→      if (!normalizedId || normalizedId === activeProfileId) {
110→        return;
111→      }
112→      setProfilesBusy(true);
113→      try {
114→        if (flushSaveRef.current) {
115→          await flushSaveRef.current();
116→        }
117→        const snapshot = await api.setActiveProfile(normalizedId);
118→        setProfilesSnapshot(snapshot);
119→        setProfilesError(null);
120→      } catch (error) {
121→        const message = error instanceof Error ? error.message : String(error);
122→        setProfilesError(message);
123→      } finally {
124→        setProfilesBusy(false);
125→      }
126→    },
127→    [activeProfileId, flushSaveRef]
128→  );
129→
130→  const createProfile = useCallback(
131→    async (input?: { name?: string; description?: string }) => {
132→      const existingNames = new Set(
133→        profiles.map((profile) => profile.name.trim().toLowerCase())
134→      );
135→      let index = 1;
136→      let fallbackName = "Profile";
137→      while (existingNames.has(fallbackName.toLowerCase())) {
138→        index += 1;
139→        fallbackName = `Profile ${index}`;
140→      }
141→      const name = input?.name?.trim() || fallbackName;
142→      const description = input?.description?.trim() ?? "";
143→
144→      setProfilesBusy(true);
145→      try {
146→        if (flushSaveRef.current) {
147→          await flushSaveRef.current();
148→        }
149→        const snapshot = await api.createProfile(name, description);
150→        setProfilesSnapshot(snapshot);
151→        setProfilesError(null);
152→      } catch (error) {
153→        const message = error instanceof Error ? error.message : String(error);
154→        setProfilesError(message);
155→      } finally {
156→        setProfilesBusy(false);
157→      }
158→    },
159→    [flushSaveRef, profiles]
160→  );
161→
162→  const updateProfile = useCallback(
163→    async (profileId: string, patch: { name?: string; description?: string }) => {
164→      const normalizedProfileId = profileId.trim();
165→      if (!normalizedProfileId) {
166→        return;
167→      }
168→      setProfilesBusy(true);
169→      try {
170→        if (flushSaveRef.current) {
171→          await flushSaveRef.current();
172→        }
173→        const snapshot = await api.updateProfile(normalizedProfileId, patch);
174→        setProfilesSnapshot(snapshot);
175→        setProfilesError(null);
176→      } catch (error) {
177→        const message = error instanceof Error ? error.message : String(error);
178→        setProfilesError(message);
179→      } finally {
180→        setProfilesBusy(false);
181→      }
182→    },
183→    [flushSaveRef]
184→  );
185→
