 28→const formatByteSize = (bytes: number) => {
 29→  if (!Number.isFinite(bytes) || bytes < 1024) {
 30→    return `${Math.max(0, Math.round(bytes))} B`;
 31→  }
 32→  const kb = bytes / 1024;
 33→  if (kb < 1024) {
