129→/// Walk git history to find the first and last commits that touched a note.
130→pub(crate) fn git_note_timestamps_from_history(
131→    root: &Path,
132→    note_rel: &str,
133→) -> Option<(Option<i64>, Option<i64>)> {
134→    let repo = Repository::open(root).ok()?;
135→    let head_oid = repo.head().ok()?.target()?;
136→    let cache_key = format!("{}|{}|{}", root.to_string_lossy(), head_oid, note_rel);
137→    {
138→        let cache = git_note_timestamps_cache();
139→        let guard = cache.lock().ok()?;
140→        if let Some(cached) = guard.get(&cache_key) {
141→            return Some(*cached);
142→        }
143→    }
144→
145→    let rel_path = Path::new(note_rel);
146→    let mut revwalk = repo.revwalk().ok()?;
147→    revwalk.push(head_oid).ok()?;
148→
149→    let mut created_ms: Option<i64> = None;
150→    let mut updated_ms: Option<i64> = None;
151→
152→    for oid_result in revwalk {
153→        let oid = oid_result.ok()?;
154→        let commit = repo.find_commit(oid).ok()?;
155→        let tree = commit.tree().ok()?;
156→        let current_blob = git_tree_blob_oid(&tree, rel_path);
157→        if current_blob.is_none() {
158→            continue;
159→        }
160→
161→        let parent_blob = if commit.parent_count() > 0 {
162→            let parent = commit.parent(0).ok()?;
163→            let parent_tree = parent.tree().ok()?;
164→            git_tree_blob_oid(&parent_tree, rel_path)
165→        } else {
166→            None
167→        };
168→
169→        if current_blob != parent_blob {
170→            let timestamp = git_commit_timestamp_ms(&commit);
171→            if updated_ms.is_none() {
172→                updated_ms = timestamp;
173→            }
174→            created_ms = timestamp;
175→        }
176→    }
177→
178→    let result = (created_ms, updated_ms);
179→    let cache = git_note_timestamps_cache();
180→    if let Ok(mut guard) = cache.lock() {
181→        guard.insert(cache_key, result);
182→    }
183→    Some(result)
184→}
