192→/// Check if a worktree contains only empty system folders and the order file.
193→fn worktree_has_only_bootstrap_artifacts(root: &Path) -> Result<bool, String> {
194→    for entry in fs::read_dir(root).map_err(|err| err.to_string())? {
195→        let entry = entry.map_err(|err| err.to_string())?;
196→        let name = entry.file_name().to_string_lossy().to_string();
197→        if name == ".git" {
198→            continue;
199→        }
200→        let path = entry.path();
201→        let metadata = entry.metadata().map_err(|err| err.to_string())?;
202→        if metadata.is_file() {
203→            if name != ORDER_FILE {
204→                return Ok(false);
205→            }
206→            continue;
207→        }
208→        if metadata.is_dir() {
209→            if !is_system_folder_name(&name) {
210→                return Ok(false);
211→            }
212→            let mut items = fs::read_dir(path).map_err(|err| err.to_string())?;
213→            if items.next().is_some() {
214→                return Ok(false);
215→            }
216→            continue;
217→        }
218→        return Ok(false);
219→    }
220→    Ok(true)
221→}
222→
223→fn clear_bootstrap_artifacts(root: &Path) -> Result<(), String> {
224→    let order_path = root.join(ORDER_FILE);
225→    if order_path.exists() {
226→        fs::remove_file(&order_path).map_err(|err| err.to_string())?;
227→    }
228→    for folder in PROTECTED_SYSTEM_FOLDERS {
229→        let path = root.join(folder);
230→        if !path.exists() {
231→            continue;
232→        }
233→        let mut items = fs::read_dir(&path).map_err(|err| err.to_string())?;
234→        if items.next().is_none() {
235→            fs::remove_dir(&path).map_err(|err| err.to_string())?;
236→        }
237→    }
238→    Ok(())
239→}
