241→/// Remove bootstrap artifacts before the first sync so the remote content wins.
242→pub(crate) fn prepare_bootstrap_worktree_for_sync(
243→    root: &Path,
244→    repo: &Repository,
245→) -> Result<(), String> {
246→    if git_head_has_commit(repo) || !git_has_changes(repo) {
247→        return Ok(());
248→    }
249→    if worktree_has_only_bootstrap_artifacts(root)? {
250→        clear_bootstrap_artifacts(root)?;
251→        return Ok(());
252→    }
253→    Err("Local changes detected. Push or commit before syncing.".to_string())
254→}
