260→        Some(value) => value,
261→        None => return (0, 0),
262→    };
263→    let local = match repo.find_branch(branch_name, git2::BranchType::Local) {
264→        Ok(branch) => branch,
265→        Err(_) => return (0, 0),
266→    };
267→    let upstream = match local.upstream() {
268→        Ok(branch) => branch,
269→        Err(_) => return (0, 0),
270→    };
271→    let local_oid = match local.get().target() {
272→        Some(value) => value,
273→        None => return (0, 0),
274→    };
275→    let upstream_oid = match upstream.get().target() {
276→        Some(value) => value,
277→        None => return (0, 0),
278→    };
279→    repo.graph_ahead_behind(local_oid, upstream_oid)
280→        .unwrap_or((0, 0))
281→}
