            #[cfg(target_os = "macos")]
            if let Some(window) = _app.get_webview_window("main") {
                let _ = apply_macos_window_alpha(&window, MACOS_WINDOW_ALPHA);
            }
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            get_security_state,
            enable_security,
            lock_security,
            unlock_security,
            set_security_preferences,
            set_native_theme,
            get_tree,
            read_note,
            create_note,
