            }
            state.known_notes.insert(job.note_rel.clone());
            state.pending.push_back(job);
            added += 1;
        }
        added
    };

    spawn_handwriting_ocr_worker_if_needed();

    let in_flight = handwriting_queue_snapshot().in_flight;

    Ok(HandwritingOcrQueueResult {
        scanned,
        queued,
        skipped,
