                        variant="destructive"
                        size="sm"
                        disabled={profilesBusy || profiles.length <= 1}
                        onClick={() => {
                          if (!window.confirm(`Delete profile "${profile.name}"?`)) {
                            return;
                          }
                          void deleteProfile(profile.id);
                        }}
                      >
                        Delete
                      </Button>
                    </div>
                  </div>
                );
              })}
            </section>
          </div>
          <DialogFooter showCloseButton />
        </DialogContent>
      </Dialog>
    </div>
